import pytest

from itsdangerous.exc import BadPayload
from itsdangerous.exc import BadSignature
from itsdangerous.url_safe import URLSafeSerializer
from itsdangerous.url_safe import URLSafeTimedSerializer


class TestURLSafeSerializerCompression:
    @pytest.fixture()
    def serializer(self):
        return URLSafeSerializer(secret_key="secret-key")

    @pytest.mark.parametrize("value", ("a" * 1000, {"data": "b" * 500}))
    def test_compression_marker_present(self, serializer, value):
        token = serializer.dumps(value)
        assert token.startswith(".")

    @pytest.mark.parametrize("value", (42, "short", {"id": 42}, [1, 2, 3]))
    def test_compression_marker_absent(self, serializer, value):
        token = serializer.dumps(value)
        assert not token.startswith(".")

    @pytest.mark.parametrize("value", ("a" * 1000, {"data": "b" * 500}))
    def test_round_trip_compressed(self, serializer, value):
        token = serializer.dumps(value)
        assert serializer.loads(token) == value

    @pytest.mark.parametrize("value", (42, "short", {"id": 42}, [1, 2, 3]))
    def test_round_trip_uncompressed(self, serializer, value):
        token = serializer.dumps(value)
        assert serializer.loads(token) == value

    def test_corrupt_compressed_payload_bad_signature(self, serializer):
        token = serializer.dumps("a" * 1000)
        assert token.startswith(".")
        payload, sig = token.rsplit(".", 1)
        # flip one character inside the base64 part: the signature no
        # longer matches, so loads raises BadSignature before the
        # payload is even decompressed
        corrupted = payload[:-2] + ("a" if payload[-2] != "a" else "b") + payload[-1] + "." + sig
        with pytest.raises(BadSignature):
            serializer.loads(corrupted)

    def test_corrupt_compressed_payload_bad_payload(self, serializer):
        token = serializer.dumps("a" * 1000)
        assert token.startswith(".")
        payload, _ = token.rsplit(".", 1)
        corrupted = payload[:-2] + ("a" if payload[-2] != "a" else "b") + payload[-1]
        # load_payload skips signature verification, so the broken
        # zlib stream surfaces as BadPayload with the original error
        with pytest.raises(BadPayload) as exc_info:
            serializer.load_payload(corrupted.encode("utf-8"))
        assert exc_info.value.original_error is not None

    @pytest.mark.parametrize("value", ("", {}))
    def test_round_trip_empty(self, serializer, value):
        token = serializer.dumps(value)
        assert not token.startswith(".")
        assert serializer.loads(token) == value

    def test_round_trip_large_dict(self, serializer):
        value = {"key": "value" * 100, "data": "x" * 500}
        token = serializer.dumps(value)
        assert token.startswith(".")
        assert serializer.loads(token) == value


class TestURLSafeTimedSerializerCompression:
    @pytest.fixture()
    def serializer(self):
        return URLSafeTimedSerializer(secret_key="secret-key")

    def test_compression_marker_present(self, serializer):
        token = serializer.dumps("a" * 1000)
        assert token.startswith(".")

    def test_round_trip_compressed(self, serializer):
        value = "a" * 1000
        token = serializer.dumps(value)
        assert serializer.loads(token) == value

